"scope_and_limits": [
{
"claim": "The findings are correlational and do not establish causal relationships; they may not generalize to other platforms, and the measure of affective polarization is limited to feelings toward party elites.",
"quotes": [
{
"text": "The analyses are observational... they do not rule out time-varying confounding, reciprocal relationships, or measurement error... The findings should overall be interpreted as associational rather than causal.",
"page": 16
},
{
"text": "This platform is a public, text-based, and highly political platform, and the associations observed here may not generalize directly to platforms with different affordances, audiences, moderation systems, or norms of interaction.",
"page": 16
},
{
"text": "Our measure of affective polarization captures feelings toward party elites rather than toward parties as institutions or ordinary party supporters... The moderation analyses should therefore be interpreted as evidence about leader-directed affective polarization.",
"page": 16
},
{
"text": "We do not draw conclusions about formal network influence, centrality, or community structure.",
"page": 15
}
]
}
